package com.labex.labexagent.run;import static org.junit.jupiter.api.Assertions.assertEquals;import static org.mockito.ArgumentMatchers.any;import static org.mockito.Mockito.*;import com.labex.entity.AgentSubagentEvent;import com.labex.mapper.AgentSubagentEventMapper;import java.util.List;import org.junit.jupiter.api.Test;
class AgentSubagentEventServiceTest {@Test void appendsTheNextSequence(){AgentSubagentEventMapper mapper=mock(AgentSubagentEventMapper.class);AgentSubagentEvent prior=new AgentSubagentEvent();prior.setSequenceNo(4L);when(mapper.selectList(any())).thenReturn(List.of(prior));AgentSubagentEvent event=new AgentSubagentEventService(mapper).append(8L,"FINAL","done");assertEquals(5L,event.getSequenceNo());verify(mapper).insert(event);}}
